<?php
declare(strict_types=1);namespace MiniErp\Repositories;use PDO;use RuntimeException;final class PlatformAdminRepository{public function __construct(private PDO $pdo){}public function count():int{return(int)$this->pdo->query('SELECT COUNT(*) FROM platform_admin_users')->fetchColumn();}public function findByEmail(string $email):?array{$s=$this->pdo->prepare('SELECT *,locked_until IS NOT NULL AND locked_until>NOW() AS is_locked FROM platform_admin_users WHERE email=? LIMIT 1');$s->execute([strtolower(trim($email))]);return$s->fetch(PDO::FETCH_ASSOC)?:null;}public function findById(int$id):?array{$s=$this->pdo->prepare('SELECT id,name,email,role,active FROM platform_admin_users WHERE id=? LIMIT 1');$s->execute([$id]);return$s->fetch(PDO::FETCH_ASSOC)?:null;}public function findActiveIdentity(int $id):?array{$s=$this->pdo->prepare('SELECT id,name,email,role FROM platform_admin_users WHERE id=? AND active=1 LIMIT 1');$s->execute([$id]);return$s->fetch(PDO::FETCH_ASSOC)?:null;}public function listTechnicalUsers():array{return$this->pdo->query("SELECT id,name,email,role,active,last_login_at,created_at FROM platform_admin_users WHERE role IN ('GLOBAL_TECH','SUPER_ADMIN') ORDER BY name,id")->fetchAll(PDO::FETCH_ASSOC);}public function create(string $name,string $email,string $hash,string $role='SUPER_ADMIN',string $source='CLI'):int{$s=$this->pdo->prepare('INSERT INTO platform_admin_users(name,email,password_hash,role,password_changed_at) VALUES(?,?,?,?,NOW())');$s->execute([trim($name),strtolower(trim($email)),$hash,$role]);$id=(int)$this->pdo->lastInsertId();$this->audit($id,'ADMIN_CREATED','platform_admin_user',(string)$id,null,['source'=>$source]);return$id;}public function loginFailed(?int $id,?string $ip):void{if($id)$this->pdo->prepare('UPDATE platform_admin_users SET failed_login_attempts=failed_login_attempts+1,locked_until=IF(failed_login_attempts>=5,DATE_ADD(NOW(),INTERVAL 15 MINUTE),locked_until) WHERE id=?')->execute([$id]);$this->audit($id,'LOGIN_FAILED','platform_admin_user',$id?(string)$id:null,$ip);}public function loginSucceeded(int $id,?string $ip):void{$this->pdo->prepare('UPDATE platform_admin_users SET failed_login_attempts=0,locked_until=NULL,last_login_at=NOW() WHERE id=?')->execute([$id]);$this->audit($id,'LOGIN_SUCCESS','platform_admin_user',(string)$id,$ip);}public function changePassword(int $id,string $hash,string $source):void{$this->pdo->prepare('UPDATE platform_admin_users SET password_hash=?,password_changed_at=NOW(),failed_login_attempts=0,locked_until=NULL WHERE id=?')->execute([$hash,$id]);$this->audit($id,'PASSWORD_CHANGED','platform_admin_user',(string)$id,null,['source'=>$source]);}public function setTechnicalUserActive(int$targetId,bool$active,int$actorId,?string$ip):void{$s=$this->pdo->prepare("UPDATE platform_admin_users SET active=?,failed_login_attempts=0,locked_until=NULL WHERE id=? AND role='GLOBAL_TECH'");$s->execute([$active?1:0,$targetId]);if($s->rowCount()!==1)throw new RuntimeException('TECHNICAL_USER_NOT_FOUND');$this->audit($actorId,$active?'GLOBAL_TECH_UNBLOCKED':'GLOBAL_TECH_BLOCKED','platform_admin_user',(string)$targetId,$ip);}public function resetTechnicalUserPassword(int$targetId,string$hash,int$actorId,?string$ip):void{$s=$this->pdo->prepare("UPDATE platform_admin_users SET password_hash=?,password_changed_at=NOW(),failed_login_attempts=0,locked_until=NULL WHERE id=? AND role='GLOBAL_TECH'");$s->execute([$hash,$targetId]);if($s->rowCount()!==1)throw new RuntimeException('TECHNICAL_USER_NOT_FOUND');$this->audit($actorId,'GLOBAL_TECH_PASSWORD_RESET','platform_admin_user',(string)$targetId,$ip);}public function deleteTechnicalUser(int$targetId,int$actorId,?string$ip):void{$this->pdo->beginTransaction();try{$target=$this->findById($targetId);if(!$target||$target['role']!=='GLOBAL_TECH')throw new RuntimeException('TECHNICAL_USER_NOT_FOUND');$this->audit($actorId,'GLOBAL_TECH_DELETED','platform_admin_user',(string)$targetId,$ip,['email'=>$target['email'],'name'=>$target['name']]);$s=$this->pdo->prepare("DELETE FROM platform_admin_users WHERE id=? AND role='GLOBAL_TECH'");$s->execute([$targetId]);if($s->rowCount()!==1)throw new RuntimeException('TECHNICAL_USER_NOT_FOUND');$this->pdo->commit();}catch(\Throwable$error){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$error;}}public function audit(?int $id,string $action,?string $targetType=null,?string $targetId=null,?string $ip=null,array $metadata=[]):void{$s=$this->pdo->prepare('INSERT INTO platform_admin_audit_log(admin_id,action,target_type,target_id,ip_address,metadata_json) VALUES(?,?,?,?,?,?)');$s->execute([$id,$action,$targetType,$targetId,$ip,$metadata?json_encode($metadata,JSON_THROW_ON_ERROR):null]);}}
